const REQUEST_TIMEOUT = 15e3

async function request(url, init) {
  const controller = new AbortController()
  const timer = setTimeout(() => controller.abort(), REQUEST_TIMEOUT)
  try {
    const res = await fetch(url, {
      ...init,
      signal: controller.signal,
    })
    if (!res.ok) throw new Error(`Request failed with status ${res.status} ${res.statusText}`)
    return await res.json()
  } finally {
    clearTimeout(timer)
  }
}
const http = {
  get: async (url, query) => {
    const _url = new URL(url)
    if (query)
      for (const [key, value] of Object.entries(query)) _url.searchParams.append(key, value)
    return await request(_url.toString())
  },
  post: async (url, data) => {
    return await request(url, {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: data ? JSON.stringify(data) : void 0,
    })
  },
}

export {http}
